/// Wavelet center frequency in Hz (`freq = centfrq(wname[, iter])`).
/// 
/// Estimates the dominant frequency of @p wname by evaluating the wavelet
/// function on its canonical `iter`-level grid (cascade for orthogonal /
/// biorthogonal families; analytical grid for continuous wavelets) and
/// taking the peak bin of the magnitude spectrum.
pub fn centfrq(ctx: &Context, args: &[&Value]) -> Result<Value, Error> {
    let mut outs = ctx.call(TOOLBOX, "centfrq", args, 1)?;
    Ok(outs.pop().unwrap())
}
pub fn centfrq_n(ctx: &Context, args: &[&Value], nargout: usize) -> Result<Vec<Value>, Error> {
    ctx.call(TOOLBOX, "centfrq", args, nargout)
}
/// Strongly-typed wrapper for `wavelet::centfrq` generated from its C++ header.
pub fn centfrq_typed(ctx: &Context, p_0_wname: &str, p_1_iter: i32) -> Result<Value, Error> {
    let v_0 = (p_0_wname).into_numkit_value()?;
    let v_1 = (p_1_iter).into_numkit_value()?;
    let mut outs = ctx.call(TOOLBOX, "centfrq", &[&v_0, &v_1], 1)?;
    Ok(outs.pop().unwrap())
}

/// Convert scales to pseudo-frequencies (`frq = scal2frq(a, wname[, delta])`).
/// 
/// Computes @f$ f = \frac{F_c}{a \cdot \Delta} @f$ where @f$ F_c = \text{centfrq}(\text{wname}) @f$.
/// 
/// @param a      Positive real scale vector (`double` or `single`).
/// @param wname  Wavelet name.
pub fn scal2frq(ctx: &Context, args: &[&Value]) -> Result<Value, Error> {
    let mut outs = ctx.call(TOOLBOX, "scal2frq", args, 1)?;
    Ok(outs.pop().unwrap())
}
pub fn scal2frq_n(ctx: &Context, args: &[&Value], nargout: usize) -> Result<Vec<Value>, Error> {
    ctx.call(TOOLBOX, "scal2frq", args, nargout)
}
/// Strongly-typed wrapper for `wavelet::scal2frq` generated from its C++ header.
pub fn scal2frq_typed(ctx: &Context, p_0_a: &Value, p_1_wname: &str, p_2_delta: f64) -> Result<Value, Error> {
    let v_1 = (p_1_wname).into_numkit_value()?;
    let v_2 = (p_2_delta).into_numkit_value()?;
    let mut outs = ctx.call(TOOLBOX, "scal2frq", &[p_0_a, &v_1, &v_2], 1)?;
    Ok(outs.pop().unwrap())
}

/// 1-D continuous wavelet transform (`[cfs, f, coi] = cwt(x[, wname][, fs], ...)`).
/// 
/// Computes the analytic continuous wavelet transform over a log-spaced scale
/// grid (`voicesPerOctave` voices per octave) via FFT-domain filter-bank
/// multiplication, with symmetric reflection boundary extension by default.
/// 
pub fn cwt(ctx: &Context, args: &[&Value]) -> Result<Value, Error> {
    let mut outs = ctx.call(TOOLBOX, "cwt", args, 1)?;
    Ok(outs.pop().unwrap())
}
