/// 1-D wavelet packet decomposition (`T = wpdec(x, n, wname[, E[, P]])`).
/// 
/// Builds a full binary wavelet-packet tree of depth `n` by recursively
/// applying @ref dwt (`wname`) to both the approximation and detail branches
/// at each level (`node 0` = root, children of `k` = `2k+1` and `2k+2`), and
/// computes @ref wentropy(`E`, `P`) at every node.
pub fn wpdec(ctx: &Context, args: &[&Value]) -> Result<Value, Error> {
    let mut outs = ctx.call(TOOLBOX, "wpdec", args, 1)?;
    Ok(outs.pop().unwrap())
}
pub fn wpdec_n(ctx: &Context, args: &[&Value], nargout: usize) -> Result<Vec<Value>, Error> {
    ctx.call(TOOLBOX, "wpdec", args, nargout)
}
/// Strongly-typed wrapper for `wavelet::wpdec` generated from its C++ header.
pub fn wpdec_typed(ctx: &Context, p_0_x: &Value, p_1_n: i32, p_2_wname: &str, p_3_entname: &str, p_4_entpar: f64) -> Result<Value, Error> {
    let v_1 = (p_1_n).into_numkit_value()?;
    let v_2 = (p_2_wname).into_numkit_value()?;
    let v_3 = (p_3_entname).into_numkit_value()?;
    let v_4 = (p_4_entpar).into_numkit_value()?;
    let mut outs = ctx.call(TOOLBOX, "wpdec", &[p_0_x, &v_1, &v_2, &v_3, &v_4], 1)?;
    Ok(outs.pop().unwrap())
}

